{"code": "seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
rc=seq.translate(str.maketrans('ACGT','TGCA'))[::-1]
stops={'TAA','TAG','TGA'}
starts={'ATG','GTG','TTG'}
def find_orfs(s, strand):
    n=len(s)
    res=[]
    for f in range(3):
        i=f
        first=None
        while i+3<=n:
            cod=s[i:i+3]
            if cod in stops:
                if first is not None:
                    res.append((first,i+3,strand,f))
                first=None
            elif cod in starts and first is None:
                first=i
            i+=3
    return res
allorfs=find_orfs(seq,'+')+find_orfs(rc,'-')
# convert to 1-based coordinates on original for plus, and reverse coordinates
rows=[]
for start,end,strand,f in allorfs:
    if strand=='+':
        s1,e1=start+1,end
    else:
        # rc coordinate to original: original position = n - rc_index (1-based)
        # rc[start:end] corresponds to original reverse complement of seq[n-end:n-start]
        s1=n-end+1; e1=n-start
    aa=(end-start)//3-1
    if aa>=50:
        rows.append((aa,strand,s1,e1,f,end-start))
for row in sorted(rows, reverse=True):
    print(row)
